#!/usr/bin/env python3
"""Pre-G2 submit-file generator (gridpacks / test jobs / pilot-production jobs) from config/sample_matrix_gen.yaml.
  make_submit_g2.py gp   <tag> name1 name2 ...             -> scripts/condor/g2_gp_<tag>.sub      (new-formula gridpack seed, outdir p2/production/hh/gridpacks)
  make_submit_g2.py test <tag> name1 ...                   -> g2_test_<tag>.sub   (2000 ev, seed_test, outdir work/test/<sample>, LHE kept)
  make_submit_g2.py prod <tag> name:njobs:nev[:k0[:flavour]] ... -> g2_prod_<tag>.sub (job k seed = seed_new(idx,10+k); outdir p2/production/hh/<sample>/)
Submit (after condor_q check): module load lxbatch/eossubmit; condor_submit <file>.  Seeds asserted unique across the whole registry + pre-G1 list by hh_samples.py."""
import yaml, os, sys
H = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); E = H.replace("/eos/home-r/", "/eos/user/r/")
PR = E.replace("/runs/multi_r1/hh", "/production/hh"); L = "/eos/user/r/rjiang/vbs_zh_codex_starter/p2/lib"
m = {s["name"]: s for s in yaml.safe_load(open(f"{H}/config/sample_matrix_gen.yaml"))["samples"]}
mode, tag, items = sys.argv[1], sys.argv[2], sys.argv[3:]
base = ["universe = vanilla", "should_transfer_files = YES", "when_to_transfer_output = ON_EXIT"]
RES = {"Q_4j_vbs_twin2": (8, 16000, "tomorrow"), "Q_bbjj_vbs_twin2": (4, 12000, "workday"), "Q_4j_vbs_twin": (8, 16000, "tomorrow"), "Q_bbjj_vbs_twin": (4, 12000, "workday"), "T_ttbar_mlm": (4, 8000, "tomorrow"), "T_ttbar_mlm_xq20": (4, 8000, "tomorrow"), "T_ttbar_mlm_xq45": (4, 8000, "tomorrow")}
def gp_dir(s): return f"{E}/work/gridpacks_v2" if s["cls"] in ("signal", "ggF_HH", "validation") and not s["seeds_new_formula"] else (f"{PR}/gridpacks" if s["seeds_new_formula"] else f"{E}/work/gridpacks")
o = [f"# GENERATED by scripts/make_submit_g2.py {mode} {tag} - do not edit by hand"] + base
if mode == "gp":
    o += [f"executable = {E}/scripts/condor/make_gridpack_hh.sh", f"arguments = $(card) $(gseed) {PR}/gridpacks $(ncore) $(pcut)",
          f"transfer_input_files = {L}/scripts/setup_stack.sh, {E}/cards/$(card).mg5, {E}/scripts/patch_cuts_vbs.py, {E}/work/models/UFO_sm_kVk2VkL.tgz, {E}/work/models/UFO_loop_sm_kl.tgz",
          f"output = {E}/work/condor/g2gp_$(card).out", f"error = {E}/work/condor/g2gp_$(card).err", f"log = {E}/work/condor/g2gp_{tag}.log",
          "request_cpus = $(ncore)", "request_memory = $(mem)", "request_disk = 20000000", '+JobFlavour = "$(flav)"', "max_retries = 1", "queue card, gseed, ncore, mem, flav, pcut from ("]
    for n in items:
        s = m[n]; assert s["seeds_new_formula"] and s["phase03_gridpack"], n
        nc, mem, fl = RES.get(n, (4, 8000, "workday")); o.append(f"  {n} {s['seed_gridpack']} {nc} {mem} {fl} {int(s['vbs_anypair_patch'])}")
elif mode in ("test", "prod"):
    o += [f"executable = {E}/scripts/condor/run_job_hh.sh",
          "arguments = $(sample) $(gp) $(nev) $INT(seed) $(cmnd) $(outdir) $(keeplhe) 0",
          f"transfer_input_files = {L}/scripts/setup_stack.sh, {L}/scripts/run_py8_delphes.sh, {E}/scripts/slim_hh_truth.py, {L}/cards/phase03_smoke/py8_common_CP5.cmnd, {E}/cards/py8/$(cmnd), {E}/cards/delphes/delphes_card_CMS_slim_hh_v1.tcl",
          f"output = {E}/work/condor/g2{mode}_$(sample).$(seed).out", f"error = {E}/work/condor/g2{mode}_$(sample).$(seed).err", f"log = {E}/work/condor/g2{mode}_{tag}.log",
          "request_cpus = 1", "request_memory = 4000", '+JobFlavour = "$(flav)"', "max_retries = 1", "success_exit_code = 0",
          "on_exit_hold = (ExitCode =?= 19)", 'on_exit_hold_reason = "gridpack not yet available"',
          "periodic_release = (HoldReasonCode =?= 3) && ((time() - EnteredCurrentStatus) > 1800) && (NumJobStarts < 20)",
          "queue sample, gp, nev, seed, cmnd, outdir, keeplhe, flav from ("]
    for it in items:
        if mode == "test":
            s = m[it]; assert s["phase03_test_job"], it
            o.append(f"  {it} {gp_dir(s)}/{it}_gridpack_s{s['seed_gridpack']}.tar.gz 2000 {s['seed_test']} {s['pythia_cmnd']} {E}/work/test/{it} 1 longlunch")
        else:
            f = it.split(":"); n, nj, nev = f[0], int(f[1]), int(f[2]); k0 = int(f[3]) if len(f) > 3 else 0; fl = f[4] if len(f) > 4 else "longlunch"
            s = m[n]; assert s["seeds_new_formula"] or True
            for k in range(k0, k0 + nj):
                assert 0 <= k < 990
                seed = 3_000_000 + 100_000 * 1 + 1000 * s["idx"] + 10 + k
                o.append(f"  {n} {gp_dir(s)}/{n}_gridpack_s{s['seed_gridpack']}.tar.gz {nev} {seed} {s['pythia_cmnd']} {PR}/{n} 0 {fl}")
o.append(")")
out = f"{H}/scripts/condor/g2_{mode}_{tag}.sub"; open(out, "w").write("\n".join(o) + "\n"); print("written", out, len(o))
